# -*- coding: utf-8 -*-
"""Table 3: IELDTM on uniform meshes and on nonuniform meshes generated by the trained PGA-DNN.

The nonuniform mesh of N points consists of N/2 uniform points and N/2 points distributed according to the
network residual (Eqs. 26-32). Errors are evaluated at the mesh nodes; '--' means that the IELDTM fails to
produce a solution (numerical overflow).
"""

import numpy as np
import torch

from utils import P, load_model, run_dir, save_tex, tex_eps, tex_num

CASES = [  # (problem, seed of the PGA-DNN model, eps values, N values)
    ('TP1', 1234, [3e-1, 3e-3, 6e-4, 1e-4], [50, 100, 200]),
    ('TP2', 5678, [1e-1, 9e-2, 1e-3, 4e-4, 1e-4], [100, 200, 300]),
    ('TP3', 1234, [1e-2, 1e-4, 1e-5, 3e-6, 1e-6], [25, 50, 100]),
]


def residual(problem, net, x, eps):
    g = torch.from_numpy(np.column_stack((x, eps * np.ones_like(x)))).float().requires_grad_(True)
    u = net(g)
    u_x = torch.autograd.grad(u, g, torch.ones_like(u), create_graph=True)[0][:, [0]]
    u_xx = torch.autograd.grad(u_x, g, torch.ones_like(u_x), create_graph=True)[0][:, [0]]
    return P.residual(problem, g, u, u_x, u_xx).detach().double().numpy().ravel()


def adaptive_mesh(problem, net, eps, n_a, m):
    """Same rule as in src/train.py (Eqs. 26-32)."""
    x = np.linspace(0, 1, n_a)
    E = residual(problem, net, x, eps) ** 2
    w = np.log1p((E[:-1] + E[1:]) / 2)
    share = w / w.sum() * m if (np.isfinite(w).all() and w.sum() > 0) else np.full(len(w), m / len(w))
    counts = np.floor(share).astype(int)
    remaining = m - counts.sum()
    if remaining > 0:
        counts[np.argsort(-(share - counts), kind='stable')[:remaining]] += 1
    new = [x[i] + (x[i + 1] - x[i]) * np.arange(1, n + 1) / (n + 1) for i, n in enumerate(counts) if n > 0]
    return np.sort(np.concatenate([x] + new))


def node_errors(problem, p, eps):
    try:
        with np.errstate(all='ignore'):
            err = P.ieldtm_coefficients(problem, p, eps, tol=1e-13)[:, 0] - P.u_exact(problem, p, eps)
            out = (np.max(np.abs(err)), np.sqrt(np.trapezoid(err ** 2, p)))
        return out if np.all(np.isfinite(out)) else (np.nan, np.nan)
    except np.linalg.LinAlgError:
        return (np.nan, np.nan)


def cell(v):
    return '--' if np.isnan(v) else '$%s$' % tex_num(v, 4)


blocks = []
for problem, seed, eps_list, Ns in CASES:
    net = load_model(run_dir(problem, 'PGA-DNN', seed))
    head = [('\\toprule' if not blocks else '\\midrule[\\heavyrulewidth]'),
            '\\multirow{3}{*}{%s} & & %s \\\\' % (problem, ' & '.join('\\multicolumn{4}{c}{$N=%d$}' % N for N in Ns)),
            '\\cmidrule(lr){3-6}\\cmidrule(lr){7-10}\\cmidrule(lr){11-14}',
            ' & & ' + ' & '.join(['\\multicolumn{2}{c}{Uniform} & \\multicolumn{2}{c}{Nonuniform}'] * 3) + ' \\\\',
            ''.join('\\cmidrule(lr){%d-%d}' % (c, c + 1) for c in range(3, 15, 2)),
            ' & $\\epsilon$' + ' & $\\|E\\|_\\infty$ & $\\|E\\|_2$' * 6 + ' \\\\', '\\midrule']
    rows = []
    print('%s (PGA-DNN seed %d)' % (problem, seed))
    for e in eps_list:
        cells = []
        for N in Ns:
            uni = node_errors(problem, np.linspace(0, 1, N), e)
            ada = node_errors(problem, adaptive_mesh(problem, net, e, N // 2, N - N // 2), e)
            cells += [cell(v) for v in (*uni, *ada)]
            print('  eps %.0e N %3d  uniform %.3e  nonuniform %.3e' % (e, N, uni[0], ada[0]))
        rows.append(' & %s & %s \\\\' % (tex_eps(e), ' & '.join(cells)))
    blocks += head + rows

save_tex('table3.tex', r'''% Preamble: \usepackage{booktabs,multirow,graphicx}
\begin{table}[p]
\centering
\vspace*{\fill}
\rotatebox{90}{%
\begin{minipage}{\textheight}
\centering
\setlength{\tabcolsep}{2pt}
\caption{Maximum absolute errors $\|E\|_\infty$ and $L_2$ errors $\|E\|_2$ of the IELDTM on uniform and
nonuniform meshes with different numbers of mesh points $N$ for TP1, TP2 and TP3. The nonuniform meshes
consist of $N/2$ uniform points and $N/2$ points generated by the trained PGA-DNN; the errors are evaluated
at the mesh nodes.}
\label{tab:ieldtm_mesh}
\resizebox{\linewidth}{!}{%
\begin{tabular}{c c cccc cccc cccc}
''' + '\n'.join(blocks) + r'''
\bottomrule
\end{tabular}%
}
\par\smallskip
{\footnotesize --: the IELDTM fails to produce a solution (numerical overflow).}
\end{minipage}%
}
\vspace*{\fill}
\end{table}
''')

